import{_ as e,c as p,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"家人","description":"高岛易断 - 家人","frontmatter":{"title":"家人","description":"高岛易断 - 家人"},"headers":[],"relativePath":"zh/classics/takashima/037.md","filePath":"zh/classics/takashima/037.md"}'),i={name:"zh/classics/takashima/037.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="家人" tabindex="-1">家人 <a class="header-anchor" href="#家人" aria-label="Permalink to “家人”">​</a></h1><h2 id="家人-1" tabindex="-1">家人 <a class="header-anchor" href="#家人-1" aria-label="Permalink to “家人”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>家人：利女贞。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>利贞两字，为《家人》一卦中关键。自古家道之成败，罔不由妇人始也，盖贤妇则称内助，淑女乃能宜家，贤而淑，则贞也，否则“牝鸡司晨，惟家之索”，是宜戒也。《易》之全经，《上经》首《乾》《坤》，《乾》为父，《坤》为母，是谓老夫妇，卦备四德，而不专在利贞；《下经》首《咸》《恒》，《咸》为妇道之始，《恒》为妇道之终。《咸》《彖》曰“利贞，娶女吉”，《恒》《彖》曰“利贞，无咎”，则知“从一而终”，“妇人贞吉”。《恒》五爻辞，显揭《家人》一卦之旨，盖贞则吉，不贞即不吉；《家人》卦德，专重夫贞，贞之吉象，专属于女，故《家人》《彖》首揭之曰：“利女贞。”</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>风自火出，家人。君子以言有物而行有恒。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>《巽》为风，《离》为火，《巽》位在巳，《离》位在午，巳午皆火，故有“风自火出”之象。按《康成别传》，见大风起，诣县曰：某日当有火灾，宜广设禁备。至时，果有火起。《左传》所谓“融风，火之始也”，即“为风自火出”之征。且风之发也，瞬息而遍及，火之起也，传燃而不尽，喻言教化之行，自内及外，其机甚捷，故曰“风自火出，家人”。考《洪范》五行，火以配言，《小畜》诸卦，风皆曰行，故君子取象于风火，以为言行。“物”，事也，“恒”，常也，火附物而生光，“言有物”而可则，风得《恒》而不易，“行有恒”而化成。言行君子之枢机，风火天地之嘘气，发迩见远，其道相同。夫闺门之内，以恩掩义，以情夺礼，所恃以慑伏《家人》者，惟赖此言行而已。教化自言行出，言行又必自诚心出，诚则足以化人，不诚则自适以阶厉，君子处家，故于言行尤兢兢焉。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：风得火而愈狂，火得风而益炽，正是时运全盛之会，然入邪则邪，入善则善，言行之间，最宜加勉。</p><p>○　问营商：《尔雅》云：“风与火为庉”，“庉”，聚也，有屯聚货物之象。爻辞曰“有物”“有恒”，物，货物，恒，恒久，谓其物不容急售，过后可获高价。</p><p>○　问功名：风行远，火炎上，有高升远到之象；言行者，出身加民之具，功名可必。</p><p>○　问家宅：防有火灾。</p><p>○　问婚姻：《家人》一卦，象取夫妇，《离》火《巽》风皆女，或长女为姊，中女为娣之象，或为两姓对结之亲。吉。</p><p>○　问疾病：是风火上升，痰多气喘之症，一时不治。</p><p>○　问六甲：生女。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>“闲”字，从门，从木，门内加木，所以防外也，故训为防。《易·文言》曰闲邪存诚，谓防闲其邪念，《论语》曰“大德不逾闲”，闲阑也，谓阑止其出入，皆取禁止防范之意。初爻处下卦之首，为《家人》之始。“有家”者，孟子谓“女有家”，是专指女子而言；“闲”者，如闺有范，女有箴，皆所以教诫之也。为女之始，先立其闲，使知所谨守，而不敢陨越，犹如蒙之必先养正也。若家渎而后严之，志变而后治之，则有悔矣。《象传》曰“志未变也”，谓其心志本明，未即邪欲，闲之于初，悔自亡也。</p><h2 id="初九占" tabindex="-1">初九占 <a class="header-anchor" href="#初九占" aria-label="Permalink to “初九占”">​</a></h2><p>○　问时运：目下好运初来，正当自知检束，斯无灾悔。</p><p>○　问战征：当行军之始，正宜整其步伐，严其号令，得以有胜无败。</p><p>○　问营商：是初次贩运，宜恪守商规。</p><p>○　问功名：是初次求名。宜遵公令，不得妄意干进。</p><p>○　问家宅：此宅墙围坚固，门户肃睦，治家者有条有则，约束详明。至四年后，可致饶富。吉。</p><p>○　问疾病：病是初起，宜自谨慎保养，必无灾害。初若不治，必致变症，则难治矣。</p><p>○　问婚姻：当初订姻好，知是家风清白，闺门素谨，可成。</p><p>○　问讼事：初讼罢之，则吉。</p><p>○　问六甲：是初胎，生女。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>二十三年十二月，友人某来，请占商法成否，筮得《家人》之《渐》。</p><p>断曰：风着物而鸣，火着物而燃，是风火皆虚，必托于物而成形，犹商业必藉资本而成事。今占问商业，而得初爻，初者，为商业谋办之始。我国自锁港以前，外商未通，一切商人，皆守旧习，未能远行，是以有悔。近始与各国贸易，所当先定商规，熟识行商之利益，犹是女子初嫁，当先学闺范，能谙为妇之礼教。为妇之道，在正家，为商之利，在裕国，其义一也。若不习之于初，而茫然从事，何能获利乎？爻辞谓“闲有家，悔亡”，家之有闲，谨其出入，商之有闲，慎其出纳，能守其闲，自有吉无悔矣。《象传》曰“志未变也”，为通商伊始，陋习犹未变也。商法必成而有大用焉。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>“无攸遂”者，谓妇道无成，事无专制也。二至四互《坎》，《坎》为酒食，故曰“在中馈”，谓朝夕以治饔飧，妇人之职也。二爻在妇妻之位，备中正之德，应九五《离》明之主，是能柔顺得正，以从事九五中正之夫者也。盖妇人之道，惟在奉祭祀、馈饮食而已，不得干预外事。《采苹》、《采蘩》两篇，皆美其能诚奉祭祀，可知妇职专在中馈，《礼》所谓“奉箕帚，操井臼”者是也。《彖传》曰“女正位乎内”，即指此爻。《象传》曰“顺以巽也”，按《象传》称“顺以《巽》”者有三：《蒙》之六五，谓事《师》之道；《渐》之六四，谓事君之道；此爻谓事夫之道。即孟子所云“以顺为正，妾妇之道”也。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问时运：目下正当大运，但爻象重阴，只宜因人成事，不能独断独行。</p><p>○　问战征：此是偏将，必非主师，或是后营，主管粮食军饷，最为紧要，谨防勿失。</p><p>○　问营商：想是贩运粮食生意，吉。</p><p>○　问功名：难以遂意。</p><p>○　问家宅：此宅朝南，宅主必是妇人，家事不能专断，惟灶基最吉。</p><p>○　问疾病：幸胃口强健，可以无害。</p><p>○　问六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>某缙绅来，请占气运，筮得《家人》之《小畜》。</p><p>断曰：二爻处下卦之中，为《离》之主，《离》象中虚，权无专制；《离》取鼎养，职在调羹。爻体以顺，爻象属阴，故只宜在内，而不在外也。今占气运，得《家人》二爻，知足下气运平顺，但才力柔弱，未得独擅大权。只可奉公从事，或者授职宫内省，正所优为也。吉。</p><p>明治三十年，占递信省气运，筮得《家人》之《小畜》。</p><p>断曰：风火《家人》，风取其疾，火取其速，皆言来往迅速也。轮船铁道，亦皆取力风火，则知卦象所云，正与递信局事，大旨相合。《家人》二爻，爻辞曰“无攸遂，在中馈，贞吉”，“无攸遂”者，谓递信，皆代人传送信物而已；“在中馈”者，谓邮函报告，铁道贩运，惟以粮食为重也。其事行诸国中，达诸海外，正内正外，亦犹是也，故曰“贞吉”。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>“嗃”，《广韵》，“严厉貌”；《玉篇》，“严大声”。嗃从口，从高，谓大其声使人畏惮也。“嘻嘻”，《玉篇》，“和乐声”；嘻从口，从喜，谓和其声使人喜悦也。九三以阳居阴，处下卦之极，为一家之主，刚严过甚，过严则伤恩，未免有厉，是嗃嗃之过也；若嘻嘻则和乐无度，过和则害义，终必见吝。盖治家之道，严虽过其中，而要之家庭肃睦，咸知敬畏，自不即于非礼，故曰“厉，吉”；和则虽上下欢悦，而荒淫佚乐，流弊有不可胜言者矣，故曰“终吝”。《象传》以失不失对勘，谓和而终吝，不如厉而得吉也。</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问时运：运限平平，终贵自勉，严谨刻苦，不自惮劳，当必获吉。若一味取乐，百事无成。</p><p>○　问战征：号令严明，万军畏服，纵不免杀戮过甚之患，而所问自得成功。</p><p>○　问营商：想是外作商店，内作住家，内外齐肃，家政严，店规谨，乃能获吉。否则，过和而流，将有名可问。</p><p>○　问功名：爻象专在宜家，功名尚缓。</p><p>○　问家宅：此宅家规严肃，吉。</p><p>○　问婚姻：九三之应在上九，曰“有孚”，知两姓相从，吉。</p><p>○　问疾病：九三属《离》为火，宜进凉剂，虽危得愈。</p><p>○　问失物：宜严急查问，可得，若宽缓则失矣。</p><p>○　问六甲：生女。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>某缙绅来，请占气运，筮得《家人》之《益》。</p><p>断曰：九三以阳居阴，刚严者也，处下体之极，为一家之长，是以刚严而督率家政也。刚严未必无悔，然较和而流者，其得多矣。足下占气运，今得此爻，知足下禀气刚强，一生处世，与卦象符合。足下职掌政务，悉以严厉治之，一时属员，未免怨苦，而于一切政务，罔不整肃，自无疏忽紊乱之弊，可以允吉。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>《离》《巽》二卦，为二女，皆自《坤》生，《坤》为富，为财，又为户，有“富家”之象。六四以阴居阴，处上卦之首，与初相应，初曰“闲有家”，盖保家有法，克勤克勤，日积月累，‘至四面俨成富家也，故曰“富家，大吉”。《象传》曰“顺在位也”，二四皆为卦主。二爻“在中馈”，中馈掌烹饪，《离》之位也；四曰“顺在位”，顺，《巽》之位也。盖妇以顺从其夫，得以致富，自能不失其职位也。</p><h2 id="六四占" tabindex="-1">六四占 <a class="header-anchor" href="#六四占" aria-label="Permalink to “六四占”">​</a></h2><p>○　问时运：目下正当盛运，已富者克保其家，未富者即发其财，大吉之象。</p><p>○　问战征：国富兵强，粮饷充足，可进可退，吉无不利。</p><p>○　问营商：“利市三倍”，立致富饶，吉可知也。</p><p>○　问功名：官与财多相反，必须破财，乃可成名。</p><p>○　问家宅：必是巨室阀阅之家，大吉。</p><p>○　问讼事：财可通神，事无不了。</p><p>○　问疾病：必是身体肥胖，膏梁过度所致，药之即愈。</p><p>○　问六甲：生女。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>近来余与友人谋创一业，占问成败吉凶如何，筮得《家人》之《同人》。</p><p>断曰：我与友人谋事，则内卦《离》属我，外卦《巽》属友，《离》《巽》方位相同，可知我与友意气相合；二四为内外卦主，可知我与友，亦各主一职，合以成事。今占得六四，四居《巽》位，《巽》为商，为利，取象于“巽，近利市三倍”，利得三倍，即可致富。此商家中大吉象也，故爻辞曰“富家，大吉”。得此占辞，决计立业，果得吉利。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>九五王位，王者以天下为一家，故推极言之。“假”与格同，谓感格也。五爻刚健中正，位居至尊，与六四相比，与六二相应，四以顺在位，二以顺相从，顺则情性相通，缠绵固结，交相爱悦，假之所由来也。一家之中，父子兄弟夫妇，情意如一，王者家大人众，推之天下，无不各长其长，各幼其幼，所谓“王假有家”，假之至矣。“勿恤，吉”者，谓王者感化之神，勿用忧恤，而自无不吉也。盖初爻曰“闲有家”，以法度闲之，为家道之始；至五曰“王假有家”，假即假其闲家之善。王有家，是化家为国，化国为天下，为王者之家，家道之终也。一说假，大也。取“假哉天命”，谓大哉天命之义。“王假有家”，谓王者大，居正，故曰《大有》家。较四之富家而更进矣，其说亦通。</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问时运：运来福至，人心自然感通，何忧不吉？</p><p>○　问战征：王者之师，所向无敌。吉。</p><p>○　问营商：想此商业，必是奉公谋办，或是贡献品物，为王家之业也，吉。</p><p>○　问功名：恰如渭水付岩，有梦卜感通之象，吉。</p><p>○　问家宅：此宅想是公卿巨邸，吉。</p><p>○　问疾病：人身以心为君，五居《巽》木，必是肝木太强生风，心火生热。药宜熄火定风，使心气开通，可勿忧也。吉。</p><p>○　问婚姻：有选入宫闱之象。</p><p>○　问六甲：生女。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>友人某来，请占气运，筮得《家人》之《贲》。</p><p>断曰：人生作事，全凭气运，运苟不佳，不特事多掣肘，即一家中，父子兄弟夫妇，亦不见信，如苏秦不第归来，嫂不下机，妻不执炊是也。气运一通，不特下民信服，且有梦通良弼，卜兆非熊，忽来王朝之征聘者，是皆运为之也。今占得五爻，五居尊位，故称“王”，“假”，格也，“勿恤”，勿忧也。知足下大运当盛，才志亦强，一年半载中，必有使命下颁，就家起用。五与二相应，二曰“中馈”，馈食也，祭也，或为祠官主祭祀，或奉公采办粮饷，不须忧恤，自能得吉。足下可拭目待之！</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上九居《巽》位之极，《巽》二阳一阴，上得乾气，《乾》为信，故“有孚”。《乾》又为威，故“威如”，且《巽》风善入，有威孚之义。离火可畏，有威严之象。合上下两体以成其爻，示人可因象以求义也。上与三应，三之“嘻嘻”，和而失节；上之“有孚”，则和顺而能感人也。三之“嗃嗃”，严近于厉；上之“威如”，则严正而若可望也。盖上为卦之终，教家之道，亦至上而成，故“终吉”。夫所谓正家者，其道不自家始也，家之本在身，先正其身，而家无不齐矣。君子不言而信，不怒而威，亦以诚之道感通之耳。《象传》曰“反身”，即《大学》所谓齐其家，在修其身之旨也。</p><h2 id="上九占" tabindex="-1">上九占 <a class="header-anchor" href="#上九占" aria-label="Permalink to “上九占”">​</a></h2><p>○　问时运：得人信服，得人敬畏，事无不成，往无不利，可行于近，亦可行于远，万事皆吉。十年好运，过此而终。</p><p>○　问战征：行车之道，有信则人不我欺，有威则人不我狎，赏罚无私，号令必行，王者之师也，故吉。</p><p>○　问营商：有信则万金可托，有威则百务皆修，商道之正也。</p><p>○　问功名：上爻处极位之地，必是身居上位，信义早孚，威望素著之大人也。</p><p>○　问家宅：此宅地位必高，为一乡之望也。吉。</p><p>○　问婚姻：两姓允从，吉。</p><p>○　问六甲：生女。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>明治二十年，占某贵显气运，筮得《家人》之《既济》。</p><p>断曰：爻居上位，适合贵显之象。爻辞曰“孚”，曰“威”，知威孚遍通夫上下，威望夙著于朝廷，所谓不言而信，不怒而威，为能得夫君子之道也，吉何如也！《彖传》曰“正家而天下定”，贵显有焉。《象》曰“反身之谓”，国之本在家，家之本在身，贵显必能身修而家齐也。气运之吉，不言可知。</p>',104)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
